#nullable enable // autogenerated

using MVZ2.Managers;
using MVZ2Logic.Audios;
using MVZ2Logic.Scenes;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.Scenes
{
    public class HealthWarningController : ScenePage
    {
        public void EnterSplash()
        {
            Main.Scene.DisplayPage(MainScenePageType.Splash);
            Main.MusicManager.Play(LogicMusicID.mainmenu);
        }
        public void SetDisplayed()
        {
            displayed = true;
            displaySeconds = 0;
        }
        public void FadeOut()
        {
            if (!displayed)
                return;
            animator.SetBool("Fade", true);
            displayed = false;
        }
        private void Awake()
        {
            receiver.OnPointerDown += OnPointerDownCallback;
        }
        private void Update()
        {
            displaySeconds += Time.deltaTime;
            if (displaySeconds >= maxDisplaySeconds)
            {
                FadeOut();
            }
        }
        private void OnPointerDownCallback(PointerEventData eventData)
        {
            FadeOut();
        }
        private static MainManager Main => MainManager.Instance;
        private bool displayed;
        private float displaySeconds;
        [SerializeField]
        private float maxDisplaySeconds = 10f;
        [SerializeField]
        private Animator animator = null!;
        [SerializeField]
        private HealthWarningRaycastReceiver receiver = null!;
    }
}
